import React, { useState } from 'react';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import Navbar from './components/Navbar';
import Footer from './components/Footer';
import Home from './components/Home';
import Product from './components/Product';
import About from './components/About';
import Contact from './components/Contact';
import Login from './components/Login';
import Admin from './components/Admin';
import AdminMessages from './components/Adminmessages';
import AdminProduct from './components/Adminproduct';
import Sidebar from './components/Sidebar';
import Cart from './components/Cart';  // Cart component'ini import ediyoruz

function App() {
  // Sepet verisini tutan state
  const [cartItems, setCartItems] = useState([]);

  // Sepete ürün ekleme fonksiyonu
  const addToCart = (product) => {
    setCartItems([...cartItems, product]);
  };

  return (
    <Router>
      <Routes>
        <Route
          path="/"
          element={
            <>
              <Navbar cartItems={cartItems} />  {/* Sepet verisini Navbar'a gönder */}
              <Home />
              <Footer />
            </>
          }
        />
        <Route
          path="/urunumuz"
          element={
            <>
              <Navbar cartItems={cartItems} />  {/* Sepet verisini Navbar'a gönder */}
              <Product addToCart={addToCart} />  {/* Sepet ekleme fonksiyonunu Product'a gönder */}
              <Footer />
            </>
          }
        />
        <Route
          path="/hakkimizda"
          element={
            <>
              <Navbar cartItems={cartItems} />  {/* Sepet verisini Navbar'a gönder */}
              <About />
              <Footer />
            </>
          }
        />
        <Route
          path="/iletisim"
          element={
            <>
              <Navbar cartItems={cartItems} />  {/* Sepet verisini Navbar'a gönder */}
              <Contact />
              <Footer />
            </>
          }
        />
        <Route
          path="/giris-yap"
          element={
            <>
              <Login />
            </>
          }
        />
        <Route
          path="/admin"
          element={
            <>
              <Admin />
            </>
          }
        />
        <Route
          path="/admin-iletisim"
          element={
            <>
              <AdminMessages />
            </>
          }
        />
        <Route
          path="/admin-urunler"
          element={
            <>
              <AdminProduct />
            </>
          }
        />
        <Route
          path="/cart"  // Sepet sayfası
          element={
            <>
              <Navbar cartItems={cartItems} />  {/* Sepet verisini Navbar'a gönder */}
              <Cart cartItems={cartItems} />  {/* Sepetteki ürünleri Cart component'ine gönder */}
              <Footer />
            </>
          }
        />
      </Routes>
    </Router>
  );
}

export default App;
